struct CWeapon { bool dead; };
struct CState {
    bool targetAlive, busy, inDanger, terminated, struck, smashed;
    CWeapon* slots[4]; int slotCount, slotIndex, sheathed, waits, performing;
    long nextFrame, frame, fps; float delay;
